-- Paso 2: importar monitores desde INVENTARIO_MONITORES.xlsx (hoja MONITORES)
-- Ejecutar sobre la base almacen_sistema ya creada en el Paso 1
SET NAMES utf8mb4;
USE almacen_sistema;

SET @cat_monitor = (SELECT id FROM categorias WHERE nombre = 'Monitor');
SET @attr_pulgadas = (SELECT id FROM categoria_atributos WHERE categoria_id = @cat_monitor AND nombre = 'Pulgadas');

START TRANSACTION;


-- Pulgadas de cada monitor

-- Historial: un movimiento de carga inicial por equipo
SELECT id, 'ENTRADA', 'Carga inicial', 'Carga inicial desde INVENTARIO_MONITORES.xlsx' FROM equipos WHERE categoria_id = @cat_monitor;

COMMIT;

-- Verificación (deben salir 109 equipos, 108 con pulgadas, 109 movimientos)
SELECT COUNT(*) AS equipos FROM equipos;
SELECT COUNT(*) AS con_pulgadas FROM equipo_atributos;
SELECT COUNT(*) AS movimientos FROM movimientos;